import React, { useState, useEffect } from 'react';

const AnalyticsDashboard = ({ currentUser, setActiveTab }) => {
    const [analyticsData, setAnalyticsData] = useState({
        totalUsers: 0,
        totalMatches: 0,
        totalMessages: 0,
        activeUsers: 0,
        avgDistance: '0 km',
        growthTrends: [0, 0, 0, 0, 0],
        engagement: [0, 0, 0, 0, 0],
        month: 'This Month'
    });
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchAnalytics = async () => {
            try {
                const API_BASE = process.env.REACT_APP_API_URL ? `${process.env.REACT_APP_API_URL}/api/user` : `http://${window.location.hostname}:5000/api/user`;
                const phone = currentUser?.phone || currentUser?.phone_number || '0712345678';

                const response = await fetch(`${API_BASE}/analytics`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ phone })
                });

                if (response.ok) {
                    const data = await response.json();
                    if (data.success) {
                        setAnalyticsData({
                            totalUsers: data.total_users || 0,
                            totalMatches: data.total_matches || 0,
                            totalMessages: data.total_messages || 0,
                            activeUsers: data.active_users || 0,
                            avgDistance: data.avg_distance || '0 km',
                            growthTrends: data.growth_trends || [0, 0, 0, 0, 0],
                            engagement: data.engagement || [0, 0, 0, 0, 0],
                            month: data.month || 'This Month'
                        });
                    }
                }
            } catch (err) {
                console.error("Failed to fetch analytics:", err);
            } finally {
                setLoading(false);
            }
        };

        fetchAnalytics();
    }, []);

    if (loading) return (
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100%', minHeight: '500px' }}>
            <div style={{ padding: '30px', fontSize: '1.2rem', color: '#64748b', fontWeight: '600' }}>Loading analytics...</div>
        </div>
    );

    return (
        <div style={{ padding: '30px', maxWidth: '1400px', margin: '0 auto', width: '100%' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '40px', flexWrap: 'wrap', gap: '15px' }}>
                <h1 style={{ fontSize: '2.5rem', color: '#0f172a', margin: 0, fontWeight: '800', letterSpacing: '-0.5px' }}>
                    📈 Analytics Dashboard
                </h1>
                <div style={{ padding: '8px 16px', backgroundColor: '#f1f5f9', borderRadius: '20px', color: '#475569', fontWeight: '700', fontSize: '0.9rem' }}>
                    Real-time Data Active
                </div>
            </div>

            {/* KPI Stat Cards */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '24px', marginBottom: '50px' }}>
                <KpiCard title="Total Users" value={analyticsData.totalUsers} gradient="linear-gradient(135deg, #3b82f6 0%, #2563eb 100%)" icon="👥" onClick={() => setActiveTab('search-matches')} />
                <KpiCard title="Total Matches" value={analyticsData.totalMatches} gradient="linear-gradient(135deg, #e11d48 0%, #be123c 100%)" icon="❤️" onClick={() => setActiveTab('matches')} />
                <KpiCard title="Total Messages" value={analyticsData.totalMessages} gradient="linear-gradient(135deg, #10b981 0%, #059669 100%)" icon="💬" onClick={() => setActiveTab('chat')} />
                <KpiCard title="Active Users" value={analyticsData.activeUsers} gradient="linear-gradient(135deg, #f59e0b 0%, #d97706 100%)" icon="🔥" onClick={() => setActiveTab('discover')} />
                <KpiCard title="Avg. Distance" value={analyticsData.avgDistance} gradient="linear-gradient(135deg, #8b5cf6 0%, #7c3aed 100%)" icon="📍" onClick={() => setActiveTab('map')} />
            </div>

            {/* Landscape Charts (Full Width) */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: '30px' }}>
                {/* Chart 1 */}
                <div style={chartContainerStyle}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%', marginBottom: '30px' }}>
                        <h3 style={{ margin: 0, color: '#f8fafc', fontSize: '1.4rem', fontWeight: '700' }}>📊 User Growth Trends</h3>
                        <span style={{ fontSize: '0.85rem', color: '#cbd5e1', backgroundColor: 'rgba(255,255,255,0.1)', padding: '4px 12px', borderRadius: '12px' }}>Last 30 Days ({analyticsData.month})</span>
                    </div>
                    <div style={{ width: '100%', height: '220px', display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', padding: '0 20px', gap: '2%', position: 'relative' }}>
                        {analyticsData.growthTrends.map((val, i) => {
                            const maxVal = Math.max(...analyticsData.growthTrends) || 1;
                            const heightPercentage = Math.max(10, Math.min(100, (val / maxVal) * 100));
                            return (
                                <div key={i} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: '100%' }}>
                                    <span style={{ color: '#94a3b8', fontSize: '0.75rem', marginBottom: '8px', fontWeight: '600' }}>{val}</span>
                                    <div style={{ ...barStyle(heightPercentage, '#60a5fa'), width: '100%', maxWidth: '40px' }} onMouseOver={(e) => {e.currentTarget.style.opacity = '1'; e.currentTarget.style.transform = 'translateY(-5px)';}} onMouseOut={(e) => {e.currentTarget.style.opacity = '0.7'; e.currentTarget.style.transform = 'translateY(0)';}}></div>
                                    <span style={{ color: '#cbd5e1', fontSize: '0.7rem', marginTop: '10px' }}>W{i+1}</span>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Chart 2 */}
                <div style={{ ...chartContainerStyle, background: 'linear-gradient(135deg, #1e1b4b 0%, #312e81 100%)', border: '1px solid rgba(139, 92, 246, 0.2)' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%', marginBottom: '30px' }}>
                        <h3 style={{ margin: 0, color: '#f8fafc', fontSize: '1.4rem', fontWeight: '700' }}>❤️ Match Engagement</h3>
                        <span style={{ fontSize: '0.85rem', color: '#cbd5e1', backgroundColor: 'rgba(255,255,255,0.1)', padding: '4px 12px', borderRadius: '12px' }}>Weekly Overview</span>
                    </div>
                    <div style={{ width: '100%', height: '220px', display: 'flex', alignItems: 'flex-end', justifyContent: 'space-around', padding: '0 20px', gap: '4%' }}>
                        {analyticsData.engagement.map((val, i) => {
                            const maxVal = Math.max(...analyticsData.engagement) || 1;
                            const heightPercentage = Math.max(10, Math.min(100, (val / maxVal) * 100));
                            return (
                                <div key={i} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: '100%' }}>
                                    <span style={{ color: '#f43f5e', fontSize: '0.75rem', marginBottom: '8px', fontWeight: 'bold' }}>{val}</span>
                                    <div style={{ ...barStyle(heightPercentage, '#f43f5e'), borderRadius: '12px 12px 0 0', width: '100%', maxWidth: '40px' }} onMouseOver={(e) => {e.currentTarget.style.opacity = '1'; e.currentTarget.style.transform = 'translateY(-5px)';}} onMouseOut={(e) => {e.currentTarget.style.opacity = '0.7'; e.currentTarget.style.transform = 'translateY(0)';}}></div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>
    );
};

